CREATE TABLE event_narrative_row(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,boundary TEXT NOT NULL,source_path TEXT NOT NULL,source_file_sha256 TEXT NOT NULL,source_blob_oid TEXT NOT NULL,ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,native_id_field TEXT,native_id TEXT,raw_json TEXT NOT NULL,raw_sha256 TEXT NOT NULL,UNIQUE(source_path,ordinal)) WITHOUT ROWID;
CREATE TABLE event_narrative_slot(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES event_narrative_row(id),owner_field TEXT NOT NULL,owner_role_status TEXT NOT NULL CHECK(owner_role_status IN ('resolved','mapping_unresolved')),locale TEXT NOT NULL,raw_locator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved_main','resolved_medium','missing','ambiguous','mapping_unresolved')),candidate_count INTEGER NOT NULL,UNIQUE(row_id,owner_field,locale)) WITHOUT ROWID;
CREATE TABLE event_narrative_text(id TEXT PRIMARY KEY,slot_id TEXT NOT NULL REFERENCES event_narrative_slot(id),source_path TEXT NOT NULL,source_file_sha256 TEXT NOT NULL,source_blob_oid TEXT NOT NULL,pair_ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,raw_text TEXT NOT NULL,raw_text_sha256 TEXT NOT NULL,UNIQUE(slot_id,source_path,pair_ordinal)) WITHOUT ROWID;
CREATE TABLE event_narrative_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE INDEX event_narrative_slot_parent ON event_narrative_slot(row_id);
CREATE INDEX event_narrative_text_slot ON event_narrative_text(slot_id);
CREATE INDEX event_narrative_text_value ON event_narrative_text(raw_text);
CREATE TRIGGER event_narrative_row_i BEFORE INSERT ON event_narrative_row WHEN EXISTS(SELECT 1 FROM event_narrative_row WHERE id=NEW.id OR (source_path=NEW.source_path AND ordinal=NEW.ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_slot_i BEFORE INSERT ON event_narrative_slot WHEN EXISTS(SELECT 1 FROM event_narrative_slot WHERE id=NEW.id OR (row_id=NEW.row_id AND owner_field=NEW.owner_field AND locale=NEW.locale)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_text_i BEFORE INSERT ON event_narrative_text WHEN EXISTS(SELECT 1 FROM event_narrative_text WHERE id=NEW.id OR (slot_id=NEW.slot_id AND source_path=NEW.source_path AND pair_ordinal=NEW.pair_ordinal)) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_release_i BEFORE INSERT ON event_narrative_release WHEN EXISTS(SELECT 1 FROM event_narrative_release) BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_row_u BEFORE UPDATE ON event_narrative_row BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_row_d BEFORE DELETE ON event_narrative_row BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_slot_u BEFORE UPDATE ON event_narrative_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_slot_d BEFORE DELETE ON event_narrative_slot BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_text_u BEFORE UPDATE ON event_narrative_text BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_text_d BEFORE DELETE ON event_narrative_text BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_release_u BEFORE UPDATE ON event_narrative_release BEGIN SELECT RAISE(ABORT,'immutable');END;
CREATE TRIGGER event_narrative_release_d BEFORE DELETE ON event_narrative_release BEGIN SELECT RAISE(ABORT,'immutable');END;
